## Why This Is Asked

Assesses practical offline-capable data loading in React Native using common libs: AsyncStorage, NetInfo, and hooks.

## Key Concepts

- AsyncStorage caching per URL
- NetInfo for connectivity state
- useEffect/useState lifecycle
- Offline-first UX and graceful degradation
- Cache invalidation and simple backoff trade-offs

## Code Example

```javascript
import { useState, useEffect } from 'react';
import NetInfo from '@react-native-community/netinfo';
import AsyncStorage from '@react-native-async-storage/async-storage';

export function useDataList(url) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const cached = await AsyncStorage.getItem(url);
      if (cached) setData(JSON.parse(cached));
      const isOnline = await NetInfo.fetch().then(s => s.isConnected);
      if (isOnline) {
        const res = await fetch(url);
        const json = await res.json();
        setData(json);
        await AsyncStorage.setItem(url, JSON.stringify(json));
      }
    } catch (e) {
      setError(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [url]);

  return { data, loading, error, refresh: () => load() };
}
```

